-- Full dump of database/klavis_ai_demo.sqlite
-- Synthetic demonstration data. No real client, legal-case or confidential LexLau/Klavis data is included.
BEGIN TRANSACTION;
CREATE TABLE ai_feedback (
    feedback_id   INTEGER PRIMARY KEY,
    ai_run_id     INTEGER NOT NULL REFERENCES ai_runs(ai_run_id),
    case_id       INTEGER REFERENCES cases(case_id),
    field_name    TEXT NOT NULL,
    feedback_type TEXT NOT NULL CHECK (feedback_type IN ('wrong_value', 'missing_value', 'format_issue',
                                       'wrong_category', 'conflict_resolved', 'false_positive')),
    comment       TEXT,                                                -- fixed vocabulary, no free text
    created_at    TEXT NOT NULL
);
CREATE TABLE ai_runs (
    ai_run_id            INTEGER PRIMARY KEY,
    document_id          INTEGER NOT NULL REFERENCES documents(document_id),
    case_id              INTEGER REFERENCES cases(case_id),
    task                 TEXT NOT NULL CHECK (task IN ('extraction', 'category_suggestion',
                                                       'summarisation', 'assistant')),
    provider_requested   TEXT NOT NULL,
    provider_used        TEXT,
    fallback_used        INTEGER NOT NULL DEFAULT 0 CHECK (fallback_used IN (0, 1)),
    fallback_reason      TEXT,
    status               TEXT NOT NULL CHECK (status IN ('success', 'error')),
    error_stage          TEXT CHECK (error_stage IN ('text_extraction', 'ai_provider')),
    error_code           TEXT,
    confidence_score     REAL CHECK (confidence_score IS NULL OR confidence_score BETWEEN 0 AND 1),
    intake_status        TEXT CHECK (intake_status IN ('Complete', 'Needs Review', 'Missing Information')),
    missing_count        INTEGER CHECK (missing_count IS NULL OR missing_count >= 0),
    conflict_count       INTEGER CHECK (conflict_count IS NULL OR conflict_count >= 0),
    processing_ms        REAL NOT NULL CHECK (processing_ms >= 0),
    latency_is_simulated INTEGER NOT NULL DEFAULT 0 CHECK (latency_is_simulated IN (0, 1)),
    retry_of_run_id      INTEGER REFERENCES ai_runs(ai_run_id),
    bug_replay           TEXT,                                         -- replay switches active, if any
    started_at           TEXT NOT NULL,
    CHECK (status = 'success' OR error_code IS NOT NULL),
    CHECK (status = 'error' OR provider_used IS NOT NULL),
    CHECK (fallback_used = 0 OR fallback_reason IS NOT NULL)
);
CREATE TABLE audit_events (
    event_id          INTEGER PRIMARY KEY,
    event_time        TEXT NOT NULL,
    event_type        TEXT NOT NULL,
    actor             TEXT NOT NULL,
    entity_type       TEXT,
    entity_id         INTEGER,
    document_id       INTEGER,
    format            TEXT,
    processing_status TEXT,
    provider          TEXT,
    latency_ms        REAL,
    error_code        TEXT,
    details           TEXT                                             -- allow-listed metadata (JSON)
);
CREATE TABLE cases (
    case_id             INTEGER PRIMARY KEY,
    case_reference      TEXT NOT NULL,
    reference_key       TEXT UNIQUE,                                   -- normalised reference: duplicate guard
    title               TEXT NOT NULL,
    client_name         TEXT NOT NULL,
    opposing_party      TEXT,
    category            TEXT NOT NULL CHECK (category IN ('Commercial dispute', 'Contract dispute',
                             'Employment matter', 'Corporate matter', 'Administrative matter', 'Other')),
    jurisdiction        TEXT,
    document_type       TEXT,
    important_dates     TEXT,                                          -- JSON list
    amounts             TEXT,                                          -- JSON list
    missing_fields      TEXT,                                          -- JSON list
    summary             TEXT,
    status              TEXT NOT NULL CHECK (status IN ('Open', 'Awaiting information', 'Closed')),
    intake_status       TEXT NOT NULL CHECK (intake_status IN ('Complete', 'Needs Review',
                                                               'Missing Information')),
    source_document_id  INTEGER NOT NULL REFERENCES documents(document_id),
    source_ai_run_id    INTEGER NOT NULL REFERENCES ai_runs(ai_run_id),
    ai_confidence       REAL CHECK (ai_confidence BETWEEN 0 AND 1),
    human_review_status TEXT NOT NULL CHECK (human_review_status IN ('Approved',
                                                                     'Approved with corrections')),
    idempotency_key     TEXT UNIQUE,
    created_by          TEXT NOT NULL,
    created_at          TEXT NOT NULL,
    updated_at          TEXT NOT NULL,
    CHECK (updated_at >= created_at)
);
CREATE TABLE documents (
    document_id        INTEGER PRIMARY KEY,
    case_id            INTEGER REFERENCES cases(case_id),           -- NULL until a case is created
    filename           TEXT    NOT NULL,
    declared_extension TEXT,
    detected_format    TEXT CHECK (detected_format IN ('pdf', 'docx', 'png', 'jpg')),
    sample_variant     TEXT CHECK (sample_variant IN ('clean', 'degraded', 'multipage',
                                   'missing_fields', 'contradictory', 'invalid', 'oversized', 'upload')),
    document_role      TEXT NOT NULL DEFAULT 'primary' CHECK (document_role IN ('primary', 'supporting')),
    byte_size          INTEGER NOT NULL CHECK (byte_size >= 0),
    pages              INTEGER CHECK (pages IS NULL OR pages >= 1),
    sha256             TEXT    NOT NULL,
    text_quality       REAL CHECK (text_quality IS NULL OR text_quality BETWEEN 0 AND 1),
    ingestion_status   TEXT NOT NULL CHECK (ingestion_status IN ('accepted', 'rejected')),
    rejection_code     TEXT,
    storage_path       TEXT,                                          -- file on disk, never the text
    uploaded_by        TEXT NOT NULL,
    uploaded_at        TEXT NOT NULL,
    CHECK (ingestion_status = 'accepted' OR rejection_code IS NOT NULL),
    CHECK (ingestion_status = 'rejected' OR detected_format IS NOT NULL)
);
CREATE TABLE extracted_fields (
    field_id       INTEGER PRIMARY KEY,
    ai_run_id      INTEGER NOT NULL REFERENCES ai_runs(ai_run_id),
    field_name     TEXT NOT NULL CHECK (field_name IN ('case_title', 'case_reference', 'client_name',
                        'opposing_party', 'document_type', 'jurisdiction', 'important_dates',
                        'amounts', 'case_category')),
    ai_value       TEXT,                                               -- JSON text for list fields
    confidence     REAL NOT NULL CHECK (confidence BETWEEN 0 AND 1),
    method         TEXT,
    is_missing     INTEGER NOT NULL CHECK (is_missing IN (0, 1)),
    has_conflict   INTEGER NOT NULL DEFAULT 0 CHECK (has_conflict IN (0, 1)),
    expected_value TEXT,                                               -- ground truth (synthetic set only)
    is_correct     INTEGER CHECK (is_correct IN (0, 1)),               -- NULL = no ground truth
    final_value    TEXT,                                               -- value after human review
    was_corrected  INTEGER CHECK (was_corrected IN (0, 1)),            -- NULL = not reviewed yet
    review_id      INTEGER REFERENCES human_reviews(review_id),
    UNIQUE (ai_run_id, field_name),
    CHECK (is_missing = 0 OR ai_value IS NULL)
);
CREATE TABLE human_reviews (
    review_id        INTEGER PRIMARY KEY,
    case_id          INTEGER NOT NULL REFERENCES cases(case_id),
    ai_run_id        INTEGER NOT NULL REFERENCES ai_runs(ai_run_id),
    reviewer         TEXT NOT NULL,                                    -- pseudonymous id
    review_type      TEXT NOT NULL CHECK (review_type IN ('intake_validation', 'post_creation_edit')),
    decision         TEXT NOT NULL CHECK (decision IN ('Approved', 'Approved with corrections')),
    fields_reviewed  INTEGER NOT NULL CHECK (fields_reviewed >= 0),
    fields_corrected INTEGER NOT NULL CHECK (fields_corrected >= 0),
    category_changed INTEGER NOT NULL DEFAULT 0 CHECK (category_changed IN (0, 1)),
    review_seconds   INTEGER CHECK (review_seconds IS NULL OR review_seconds >= 0),
    is_simulated     INTEGER NOT NULL DEFAULT 0 CHECK (is_simulated IN (0, 1)),
    reviewed_at      TEXT NOT NULL,
    CHECK (fields_corrected <= fields_reviewed),
    CHECK ((decision = 'Approved') = (fields_corrected = 0))
);
CREATE TABLE test_results (
    result_id        INTEGER PRIMARY KEY,
    test_run_id      INTEGER NOT NULL REFERENCES test_runs(test_run_id),
    scenario_code    TEXT NOT NULL CHECK (scenario_code GLOB 'TEST [0-9][0-9][0-9]'),
    scenario_name    TEXT NOT NULL,
    document_format  TEXT,
    expected         TEXT NOT NULL,
    observed         TEXT NOT NULL,
    status           TEXT NOT NULL CHECK (status IN ('PASS', 'FAIL')),
    failure_category TEXT,
    is_regression    INTEGER NOT NULL DEFAULT 0 CHECK (is_regression IN (0, 1)),
    duration_ms      REAL NOT NULL CHECK (duration_ms >= 0),
    UNIQUE (test_run_id, scenario_code),
    CHECK (status = 'PASS' OR failure_category IS NOT NULL)
);
CREATE TABLE test_runs (
    test_run_id  INTEGER PRIMARY KEY,
    run_label    TEXT NOT NULL,
    code_version TEXT NOT NULL,
    bug_replay   TEXT,
    trigger      TEXT NOT NULL CHECK (trigger IN ('ci', 'manual', 'ui')),
    started_at   TEXT NOT NULL,
    finished_at  TEXT NOT NULL,
    tests_total  INTEGER NOT NULL CHECK (tests_total >= 0),
    tests_passed INTEGER NOT NULL CHECK (tests_passed >= 0),
    tests_failed INTEGER NOT NULL CHECK (tests_failed >= 0),
    CHECK (tests_passed + tests_failed = tests_total),
    CHECK (finished_at >= started_at)
);
CREATE INDEX ix_documents_case ON documents(case_id);
CREATE INDEX ix_documents_sha ON documents(sha256);
CREATE INDEX ix_ai_runs_document ON ai_runs(document_id);
CREATE INDEX ix_ai_runs_case ON ai_runs(case_id);
CREATE INDEX ix_ai_runs_task_status ON ai_runs(task, status);
CREATE INDEX ix_fields_run ON extracted_fields(ai_run_id);
CREATE INDEX ix_reviews_case ON human_reviews(case_id);
CREATE INDEX ix_results_run ON test_results(test_run_id);
CREATE INDEX ix_audit_time ON audit_events(event_time);
CREATE VIEW vw_extraction_runs AS
SELECT r.ai_run_id, r.document_id, r.case_id, r.provider_requested, r.provider_used,
       r.fallback_used, r.fallback_reason, r.status, r.error_stage, r.error_code,
       r.confidence_score, r.intake_status, r.missing_count, r.conflict_count,
       r.processing_ms, r.latency_is_simulated, r.retry_of_run_id, r.started_at,
       d.detected_format,
       CASE d.detected_format WHEN 'pdf' THEN 'PDF' WHEN 'docx' THEN 'DOCX' ELSE 'Image' END AS file_family,
       d.sample_variant, d.pages, d.text_quality
FROM ai_runs r
JOIN documents d ON d.document_id = r.document_id
WHERE r.task = 'extraction';
CREATE VIEW vw_field_facts AS
SELECT f.field_id, f.ai_run_id, f.field_name, f.confidence, f.is_missing, f.has_conflict,
       f.is_correct, f.was_corrected,
       CASE WHEN f.expected_value IS NOT NULL THEN 1 ELSE 0 END AS expected_present,
       CASE WHEN f.expected_value IS NOT NULL AND f.ai_value IS NOT NULL THEN 1 ELSE 0 END AS found_when_present,
       e.detected_format, e.file_family, e.sample_variant, e.provider_used, e.started_at
FROM extracted_fields f
JOIN vw_extraction_runs e ON e.ai_run_id = f.ai_run_id;
CREATE VIEW vw_ai_quality_summary AS
WITH runs AS (
    SELECT COUNT(*) AS extraction_runs,
           SUM(status = 'success') AS successful_runs,
           SUM(status = 'error') AS failed_runs,
           SUM(fallback_used) AS fallback_runs,
           AVG(CASE WHEN status = 'success' THEN confidence_score END) AS avg_confidence,
           AVG(processing_ms) AS avg_processing_ms,
           SUM(status = 'success' AND intake_status <> 'Complete') AS runs_needing_review
    FROM vw_extraction_runs
), fields AS (
    SELECT SUM(is_correct) AS correct_fields,
           COUNT(is_correct) AS scored_fields,
           SUM(found_when_present) AS found_fields,
           SUM(expected_present) AS expected_fields,
           SUM(was_corrected) AS corrected_fields,
           COUNT(was_corrected) AS reviewed_fields
    FROM vw_field_facts
), tests AS (
    SELECT tests_total, tests_passed FROM test_runs ORDER BY test_run_id DESC LIMIT 1
)
SELECT r.extraction_runs, r.successful_runs, r.failed_runs,
       ROUND(100.0 * r.successful_runs / r.extraction_runs, 1)            AS ai_success_rate_pct,
       ROUND(100.0 * r.failed_runs / r.extraction_runs, 1)                AS error_rate_pct,
       r.fallback_runs,
       ROUND(100.0 * r.fallback_runs / r.extraction_runs, 1)              AS fallback_rate_pct,
       ROUND(r.avg_confidence, 3)                                         AS avg_confidence,
       ROUND(r.avg_processing_ms, 0)                                      AS avg_processing_ms,
       r.runs_needing_review,
       ROUND(100.0 * r.runs_needing_review / r.successful_runs, 1)        AS human_review_rate_pct,
       ROUND(100.0 * f.correct_fields / f.scored_fields, 1)               AS field_accuracy_pct,
       ROUND(100.0 * f.found_fields / f.expected_fields, 1)               AS completeness_pct,
       f.corrected_fields,
       ROUND(100.0 * f.corrected_fields / f.reviewed_fields, 1)           AS manual_correction_rate_pct,
       (SELECT COUNT(*) FROM cases)                                       AS cases_created,
       (SELECT ROUND(100.0 * tests_passed / tests_total, 1) FROM tests)   AS latest_test_pass_rate_pct
FROM runs r CROSS JOIN fields f;
CREATE VIEW vw_document_type_performance AS
WITH runs AS (
    SELECT file_family, detected_format, sample_variant,
           COUNT(*) AS runs, SUM(status = 'success') AS successful_runs,
           SUM(fallback_used) AS fallback_runs,
           AVG(CASE WHEN status = 'success' THEN confidence_score END) AS avg_confidence,
           AVG(processing_ms) AS avg_processing_ms,
           SUM(status = 'success' AND intake_status <> 'Complete') AS needing_review
    FROM vw_extraction_runs GROUP BY 1, 2, 3
), fields AS (
    SELECT file_family, detected_format, sample_variant,
           SUM(is_correct) AS correct, COUNT(is_correct) AS scored,
           SUM(found_when_present) AS found, SUM(expected_present) AS expected,
           SUM(was_corrected) AS corrected, COUNT(was_corrected) AS reviewed
    FROM vw_field_facts GROUP BY 1, 2, 3
)
SELECT r.file_family, r.detected_format, r.sample_variant, r.runs, r.successful_runs,
       ROUND(100.0 * r.successful_runs / r.runs, 1)     AS success_rate_pct,
       ROUND(100.0 * r.fallback_runs / r.runs, 1)       AS fallback_rate_pct,
       ROUND(r.avg_confidence, 3)                       AS avg_confidence,
       ROUND(r.avg_processing_ms, 0)                    AS avg_processing_ms,
       ROUND(100.0 * f.correct / f.scored, 1)           AS field_accuracy_pct,
       ROUND(100.0 * f.found / f.expected, 1)           AS completeness_pct,
       ROUND(100.0 * f.corrected / f.reviewed, 1)       AS manual_correction_rate_pct,
       ROUND(100.0 * r.needing_review / r.successful_runs, 1) AS human_review_rate_pct
FROM runs r
LEFT JOIN fields f USING (file_family, detected_format, sample_variant);
CREATE VIEW vw_field_accuracy AS
SELECT field_name,
       COUNT(*)                                             AS extractions,
       COUNT(is_correct)                                    AS scored,
       SUM(is_correct)                                      AS correct,
       ROUND(100.0 * SUM(is_correct) / COUNT(is_correct), 1) AS accuracy_pct,
       ROUND(100.0 * SUM(found_when_present) / NULLIF(SUM(expected_present), 0), 1) AS completeness_pct,
       ROUND(100.0 * SUM(is_missing) / COUNT(*), 1)         AS missing_rate_pct,
       SUM(has_conflict)                                    AS conflicts,
       SUM(was_corrected)                                   AS manual_corrections,
       ROUND(100.0 * SUM(was_corrected) / NULLIF(COUNT(was_corrected), 0), 1) AS correction_rate_pct,
       ROUND(AVG(CASE WHEN is_missing = 0 THEN confidence END), 3) AS avg_confidence_when_found
FROM vw_field_facts
GROUP BY field_name;
CREATE VIEW vw_test_run_summary AS
SELECT t.test_run_id, t.run_label, t.code_version, COALESCE(t.bug_replay, '') AS bug_replay,
       t.trigger, t.started_at, t.tests_total, t.tests_passed, t.tests_failed,
       ROUND(100.0 * t.tests_passed / t.tests_total, 1) AS pass_rate_pct,
       (SELECT COUNT(*) FROM test_results r WHERE r.test_run_id = t.test_run_id
                                              AND r.is_regression = 1) AS regressions,
       (SELECT GROUP_CONCAT(scenario_code, ', ') FROM test_results r
         WHERE r.test_run_id = t.test_run_id AND r.status = 'FAIL') AS failed_scenarios
FROM test_runs t;
CREATE VIEW vw_human_review_metrics AS
SELECT substr(h.reviewed_at, 1, 7)                          AS review_month,
       COUNT(*)                                             AS reviews,
       SUM(h.decision = 'Approved with corrections')        AS reviews_with_corrections,
       ROUND(100.0 * SUM(h.decision = 'Approved with corrections') / COUNT(*), 1) AS reviews_with_corrections_pct,
       SUM(h.fields_reviewed)                               AS fields_reviewed,
       SUM(h.fields_corrected)                              AS fields_corrected,
       ROUND(100.0 * SUM(h.fields_corrected) / SUM(h.fields_reviewed), 1) AS field_correction_rate_pct,
       SUM(h.category_changed)                              AS category_changes,
       ROUND(AVG(h.review_seconds), 0)                      AS avg_review_seconds,
       SUM(c.intake_status <> 'Complete')                   AS cases_needing_review
FROM human_reviews h
JOIN cases c ON c.case_id = h.case_id
WHERE h.review_type = 'intake_validation'
GROUP BY 1;
CREATE VIEW vw_error_analysis AS
SELECT r.task,
       COALESCE(r.error_stage, 'ai_provider')               AS error_stage,
       r.error_code,
       COALESCE(d.detected_format, 'unknown')               AS detected_format,
       COUNT(*)                                             AS failed_runs,
       SUM(EXISTS (SELECT 1 FROM ai_runs x WHERE x.retry_of_run_id = r.ai_run_id
                                              AND x.status = 'success')) AS recovered_by_retry,
       MIN(r.started_at)                                    AS first_seen,
       MAX(r.started_at)                                    AS last_seen
FROM ai_runs r
JOIN documents d ON d.document_id = r.document_id
WHERE r.status = 'error'
GROUP BY 1, 2, 3, 4;
COMMIT;
